package com.guocheng.mediapocket;
import android.app.*;import android.content.*;import android.os.Build;import android.view.*;
public final class FullscreenMode {
 static SharedPreferences prefs(Activity a){return a.getSharedPreferences("data",0);}
 static void apply(Activity a,String mode,boolean reset)throws Exception{mode=FullscreenRules.mode(mode,true);SharedPreferences p=prefs(a);SharedPreferences.Editor e=p.edit().putString("aspectMode",mode).putFloat("gestureZoom",1f).putBoolean("fullscreenNoCrop.v1",true);if(reset)e.putFloat("zoomX",1f).putFloat("zoomY",1f);e.apply();SourceSubtitleLoader.set(a,"zoom",1f);immersive(a);Object video=OnlineSubtitleSearch.field(a,"video");if(video!=null)OnlineSubtitleSearch.call(video,"aspect",new Class<?>[]{String.class},FullscreenRules.layoutMode(mode));applyZoom(a);}
 /** 横屏沉浸时让视频区域覆盖刘海/挖孔区域。 */
 static void immersive(Activity a){try{if(Build.VERSION.SDK_INT<28)return;WindowManager.LayoutParams w=a.getWindow().getAttributes();int want=Build.VERSION.SDK_INT>=30?3:1;if(w.layoutInDisplayCutoutMode!=want){w.layoutInDisplayCutoutMode=want;a.getWindow().setAttributes(w);}}catch(Exception ignored){}}
 public static void initialize(Object session){try{Object owner=OnlineSubtitleSearch.field(session,"a");if(!(owner instanceof Activity))return;Activity a=(Activity)owner;SharedPreferences p=prefs(a);boolean migrated=p.getBoolean("fullscreenNoCrop.v1",false);{String was=p.getString("aspectMode",null),now=FullscreenRules.mode(was,true);if(!now.equals(was))p.edit().putString("aspectMode",now).apply();}String mode=PlaybackPrefs.rememberAspect(p)?FullscreenRules.mode(p.getString("aspectMode","smart"),migrated):"smart";apply(a,mode,!migrated||!PlaybackPrefs.rememberAspect(p));PlayerSwitches.restoreBrightness(a);installPinch(a);PlayerGestures.install(a);PlayerChrome.install(a);PlaybackPrefs.attach(a);TrackSelection.attach(a);}catch(Exception ignored){}}
 public static void sync(Activity a){try{apply(a,prefs(a).getString("aspectMode","smart"),false);}catch(Exception ignored){}}
 /** 替换 GesturePlayerActivity.applyZoom：按轴独立缩放，始终以画面中心为轴心。 */
 public static void applyZoom(Object owner){if(owner instanceof Activity&&scaleSurface((Activity)owner))PlayerChrome.tick((Activity)owner);}
 /** 0.1.152：智能满屏要等视频尺寸出来、横竖屏或分屏变化后重算；PlayerChrome 每 250ms 调一次，只改缩放、不触发刷新。 */
 static void smartTick(Activity a){if("smart".equals(prefs(a).getString("aspectMode","")))scaleSurface(a);}
 static boolean scaleSurface(Activity a){try{Object video=OnlineSubtitleSearch.field(a,"video");if(video==null)return false;Object s=OnlineSubtitleSearch.field(video,"surface");if(!(s instanceof View))return false;View v=(View)s;SourceSubtitleLoader.set(a,"lastSurface",v);SharedPreferences p=prefs(a);float k=1f;if("original".equals(p.getString("aspectMode","smart"))){Object vw=OnlineSubtitleSearch.field(video,"vw");k=FullscreenRules.originalScale(v.getWidth(),vw instanceof Integer?(Integer)vw:0);}float sx=1f,sy=1f;if("smart".equals(p.getString("aspectMode","smart"))){View screen=a.getWindow().getDecorView();Object vw=OnlineSubtitleSearch.field(video,"vw"),vh=OnlineSubtitleSearch.field(video,"vh");float[] f=FullscreenRules.smart(screen.getWidth(),screen.getHeight(),vw instanceof Integer?(Integer)vw:0,vh instanceof Integer?(Integer)vh:0);sx=f[0];sy=f[1];}float x=k*sx*FullscreenRules.clamp(p.getFloat("zoomX",1f)),y=k*sy*FullscreenRules.clamp(p.getFloat("zoomY",1f));v.setPivotX(v.getWidth()/2f);v.setPivotY(v.getHeight()/2f);v.setTranslationX(0);v.setTranslationY(0);if(v.getScaleX()!=x)v.setScaleX(x);if(v.getScaleY()!=y)v.setScaleY(y);return true;}catch(Exception ignored){return false;}}
 static void hud(Activity a,String text){try{OnlineSubtitleSearch.call(a,"showHud",new Class<?>[]{String.class},text);}catch(Exception ignored){}}
 static void installPinch(Activity a)throws Exception{ScaleGestureDetector d=new ScaleGestureDetector(a,new ScaleGestureDetector.SimpleOnScaleGestureListener(){
  @Override public boolean onScaleBegin(ScaleGestureDetector g){try{OnlineSubtitleSearch.call(a,"controls",new Class<?>[]{boolean.class},false);}catch(Exception ignored){}return true;}
  @Override public boolean onScale(ScaleGestureDetector g){SharedPreferences p=prefs(a);float[] f=FullscreenRules.axisScale(g.getCurrentSpanX(),g.getPreviousSpanX(),g.getCurrentSpanY(),g.getPreviousSpanY());float x=FullscreenRules.clamp(p.getFloat("zoomX",1f)*f[0]),y=FullscreenRules.clamp(p.getFloat("zoomY",1f)*f[1]);p.edit().putFloat("zoomX",x).putFloat("zoomY",y).apply();applyZoom(a);hud(a,"横向 "+Math.round(x*100)+"% · 纵向 "+Math.round(y*100)+"%");return true;}
  @Override public void onScaleEnd(ScaleGestureDetector g){PlayerChrome.refresh(a);}}){@Override public boolean onTouchEvent(MotionEvent e){return !PlayerGestures.locked(a)&&super.onTouchEvent(e);}};
  d.setQuickScaleEnabled(false);SourceSubtitleLoader.set(a,"pinch",d);}
 /** 在 onDoubleTap 最前面调用：已缩放时双击中间区域恢复当前比例模式，返回 true 则跳过快进/快退。 */
 public static boolean doubleTap(Object listener,MotionEvent e){try{Object owner=OnlineSubtitleSearch.field(listener,"this$0");if(!(owner instanceof Activity)||e==null)return false;Activity a=(Activity)owner;int w=a.getWindow().getDecorView().getWidth();if(w>0&&(e.getX()<w/3f||e.getX()>w*2f/3f))return false;return doubleTapCenter(a);}catch(Exception ex){return false;}}
 /** 中间三分之一双击：已缩放时恢复当前比例模式。 */
 static boolean doubleTapCenter(Activity a){try{SharedPreferences p=prefs(a);if(p.getFloat("zoomX",1f)==1f&&p.getFloat("zoomY",1f)==1f)return false;String mode=p.getString("aspectMode","smart");apply(a,mode,true);PlayerChrome.refresh(a);hud(a,"已恢复 · "+FullscreenRules.LABELS[FullscreenRules.index(mode)]);return true;}catch(Exception ex){return false;}}
 /** 比例按钮：切到下一模式、记住，并恢复 100% 缩放。顺序见 FullscreenRules.next。 */
 public static String cycle(Activity a)throws Exception{String mode=FullscreenRules.next(prefs(a).getString("aspectMode","smart"));apply(a,mode,true);PlayerChrome.refresh(a);return FullscreenRules.LABELS[FullscreenRules.index(mode)];}
 /** 顶栏单击：适应 → 拉伸 → 裁切。 */
 public static String quick(Activity a)throws Exception{String mode=FullscreenRules.quickNext(prefs(a).getString("aspectMode","smart"));apply(a,mode,true);PlayerChrome.refresh(a);return FullscreenRules.LABELS[FullscreenRules.index(mode)];}
 /** GesturePlayerActivity.aspect：点一下立刻切到下一种画面比例，不弹菜单，也不显示模式名。 */
 public static void choose(Object owner){if(!(owner instanceof Activity))return;Activity a=(Activity)owner;try{String label=cycle(a);String announce=FullscreenRules.cycleHud(label);if(announce!=null)hud(a,announce);}catch(Exception e){OnlineSubtitleSearch.message(a,"比例设置失败："+e.getClass().getSimpleName());}}
}
